$ErrorActionPreference='Stop';$ProjectRoot=[IO.Path]::GetFullPath($ProjectRoot);if(!$BuildRoot){$BuildRoot=Join-Path $ProjectRoot 'out/staging'};$BuildRoot=[IO.Path]::GetFullPath($BuildRoot)
Add-Type -Path (Join-Path $PSScriptRoot 'PrivateDesktop.cs');Add-Type -Path (Join-Path $PSScriptRoot 'NativeChatTest.cs');Add-Type -AssemblyName System.Drawing
Add-Type -TypeDefinition @'
using System;using System.Runtime.InteropServices;
public static class TvWindow {
 [StructLayout(LayoutKind.Sequential)]struct Point{public int x,y;}
 [StructLayout(LayoutKind.Sequential)]struct Rect{public int left,top,right,bottom;}
 [DllImport("user32.dll")]static extern bool GetWindowRect(IntPtr window,out Rect rect);
 [DllImport("user32.dll")]static extern bool ClientToScreen(IntPtr window,ref Point point);
 [DllImport("user32.dll")]static extern int GetWindowRgn(IntPtr window,IntPtr region);
 [DllImport("gdi32.dll")]static extern IntPtr CreateRectRgn(int left,int top,int right,int bottom);
 [DllImport("gdi32.dll")]static extern bool PtInRegion(IntPtr region,int x,int y);
 [DllImport("gdi32.dll")]static extern bool DeleteObject(IntPtr value);
 [DllImport("user32.dll")]public static extern bool SetWindowPos(IntPtr window,IntPtr after,int x,int y,int width,int height,uint flags);
 public static int[] ChildBounds(IntPtr parent,IntPtr child){var p=new Point();ClientToScreen(parent,ref p);Rect r;GetWindowRect(child,out r);return new[]{r.left-p.x,r.top-p.y,r.right-r.left,r.bottom-r.top};}
 public static long ScreenPoint(IntPtr window,int x,int y){var p=new Point{x=x,y=y};ClientToScreen(window,ref p);return (long)(uint)((p.y<<16)|(p.x&65535));}
 public static bool Rounded(IntPtr window){var region=CreateRectRgn(0,0,1,1);try{Rect r;GetWindowRect(window,out r);return GetWindowRgn(window,region)>0&&!PtInRegion(region,0,0)&&PtInRegion(region,(r.right-r.left)/2,(r.bottom-r.top)/2);}finally{DeleteObject(region);}}
}
'@
$root=Join-Path $ProjectRoot ('artifacts/television-desktop-'+[Guid]::NewGuid().ToString('N'));New-Item -ItemType Directory -Force $root|Out-Null;$desktop=$null;$service=$null;$provider=$null;$checks=0
$env:HIBERNATION_SESSION_KEY='television-chrome-fixture';$env:TEMP="$BuildRoot/tmp";$env:TMP=$env:TEMP
function Check($Value,$Name){if(!$Value){throw "CHECK FAILED: $Name"};$script:checks++;Write-Output "PASS $Name"}
function Wait-For([scriptblock]$Probe,$Name,[int]$Seconds=25){$end=[DateTime]::UtcNow.AddSeconds($Seconds);while([DateTime]::UtcNow-lt$end){if(& $Probe){return};Start-Sleep -Milliseconds 35};try{Api '/api/capabilities'|ConvertTo-Json -Depth 35|Set-Content "$root/timeout.json"}catch{};throw "TIMEOUT $Name"}
function Api($Path,$Data=$null){$a=@{Uri=$script:origin+$Path;Headers=@{Authorization='Bearer television-chrome-fixture'};TimeoutSec=12};if($null-ne$Data){$a.Method='Post';$a.ContentType='application/json';$a.Body=[Text.Encoding]::UTF8.GetBytes(($Data|ConvertTo-Json -Depth 35 -Compress))};Invoke-RestMethod @a}
function Tv{(Api '/api/capabilities').plugins.Where({$_.id-eq'television'})[0].current}
function Plugin($Name,$Arguments){$null=Api '/api/plugin/test' @{tool=$Name;args=$Arguments};Wait-For {$script:result=Api '/api/plugin/result';$script:result.state-in@('succeeded','failed')} $Name;return $script:result.result}
function Appearance($Style,$Palette){$settings=(Api '/api/dashboard').settings;$settings.plugins.television.frameStyle=$Style;$settings.plugins.television.framePalette=$Palette;$null=Api '/api/settings' @{settings=$settings}}
function Bitmap{$capture=$desktop.CaptureClient($window);for($pixel=3;$pixel-lt$capture.Bgra.Length;$pixel+=4){$capture.Bgra[$pixel]=255};$image=New-Object Drawing.Bitmap($capture.Width,$capture.Height);$rect=New-Object Drawing.Rectangle(0,0,$capture.Width,$capture.Height);$bits=$image.LockBits($rect,[Drawing.Imaging.ImageLockMode]::WriteOnly,[Drawing.Imaging.PixelFormat]::Format32bppArgb);try{[Runtime.InteropServices.Marshal]::Copy($capture.Bgra,0,$bits.Scan0,$capture.Bgra.Length)}finally{$image.UnlockBits($bits)};return $image}
function FrameHash{$image=Bitmap;try{$pane=(Tv).screen_rect;$rect=New-Object Drawing.Rectangle($pane.x,$pane.y,$pane.width,$pane.height);$crop=$image.Clone($rect,[Drawing.Imaging.PixelFormat]::Format32bppArgb);$stream=New-Object IO.MemoryStream;try{$crop.Save($stream,[Drawing.Imaging.ImageFormat]::Png);[Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($stream.ToArray()))}finally{$crop.Dispose();$stream.Dispose()}}finally{$image.Dispose()}}
try{
 $provider=Start-Process "$BuildRoot/Hibernation_TestProvider.exe" -ArgumentList ('"'+$root+'/provider"') -WindowStyle Hidden -PassThru -RedirectStandardOutput "$root/provider.log" -RedirectStandardError "$root/provider-error.log";Wait-For {Test-Path "$root/provider/port"} 'provider';$fixture='http://127.0.0.1:'+(Get-Content "$root/provider/port")
 $cfg=Get-Content "$ProjectRoot/config/example.json" -Raw|ConvertFrom-Json -AsHashtable;$cfg.dataRoot="$root/data";$cfg.characterRoot="$ProjectRoot/character";$cfg.uiRoot="$ProjectRoot/ui";$cfg.pluginRoot="$BuildRoot/plugins";$cfg.profiles=@($cfg.profiles[0]);$cfg.solitudeIntervalMs=604800000;$cfg.idleBeforeSolitudeMs=86400000;$cfg.plugins=@{television=@{enabled=$true;volume=0;wakeOnEnd=$false;frameStyle='television';framePalette='sage';platforms=@(@{id='fixture';name='本机影像';enabled=$true;hosts=@('127.0.0.1');homeUrl=$fixture+'/fixture/tv-chrome';searchUrl=$fixture+'/fixture/tv-chrome?q={query}'})}};$cfg|ConvertTo-Json -Depth 35|Set-Content "$root/config.json" -Encoding utf8
 $desktop=[PrivateDesktop]::new("$BuildRoot/hibernation-agent.exe","$root/config.json","$root/ready.json",$ProjectRoot);$service=$desktop.Child;Wait-For {if($service.HasExited){throw "TV fixture exited $($service.ExitCode)"};Test-Path "$root/ready.json"} 'backend';$script:origin='http://127.0.0.1:'+((Get-Content "$root/ready.json" -Raw|ConvertFrom-Json).port);$null=Api '/api/surfaces/show' @{id='television'};$script:window=$desktop.Find('HibernationFloatingTelevision');Wait-For {[ChatWindowTest]::IsWindowVisible($window)} 'TV visible'
 Check ($window-ne[IntPtr]::Zero-and((Tv).frame_style-eq'television')) 'framed television belongs only to the private fixture';Check (([ChatWindowTest]::GetWindowLongPtrW($window,-16).ToInt64()-band0xC00000)-eq0-and[TvWindow]::Rounded($window)) 'television has rounded independent chrome without a native caption';$play=[ChatWindowTest]::GetDlgItem($window,3502);$power=[ChatWindowTest]::GetDlgItem($window,3501);$stop=[ChatWindowTest]::GetDlgItem($window,3503);Check ([ChatWindowTest]::IsWindowVisible($play)-and[ChatWindowTest]::IsWindowVisible($power)-and[ChatWindowTest]::IsWindowVisible($stop)) 'native play stop and hide controls are visible'
 [ChatWindowTest]::UseWindowCoordinates($window);$button=[TvWindow]::ChildBounds($window,$power);Check ([ChatWindowTest]::Send($window,0x84,0,([TvWindow]::ScreenPoint($window,($button[0]+10),($button[1]+10))))-eq1) 'controls are clickable rather than caption drag regions';Check ([ChatWindowTest]::Send($window,0x84,0,([TvWindow]::ScreenPoint($window,2,2)))-eq13) 'outer corner retains resize hit testing'
 New-Item -ItemType Directory -Force "$root/data/materials"|Out-Null;Invoke-WebRequest ($fixture+'/clip.mp4') -OutFile "$root/data/materials/chrome.mp4"; $opened=Plugin 'television.open' @{source='materials/chrome.mp4';title='实际的合成影像'};Check $opened.ok 'video still opens through the engine player';Wait-For {(Tv).state-eq'playing'-and(Tv).frame_width-gt0-and(Tv).sync_source-eq'AudioMaster'} 'actual decoded image and engine audio clock';Check ((Tv).playback_engine-eq'AYVideoPlayer'-and(Tv).sync_source-eq'AudioMaster') 'frame chrome retains engine audio-master synchronization';$null=[ChatWindowTest]::Send($window,0x111,3502);Wait-For {(Tv).state-eq'paused'} 'native pause';$position=(Tv).position_seconds;Start-Sleep -Milliseconds 200;Check ([math]::Abs((Tv).position_seconds-$position)-lt.03) 'native pause stops the actual media clock'
 $image=Bitmap;try{$shell=$image.GetPixel(12,50);$pane=(Tv).screen_rect;$colors=[Collections.Generic.HashSet[int]]::new();for($x=$pane.x+20;$x-lt$pane.x+$pane.width-20;$x+=13){for($y=$pane.y+20;$y-lt$pane.y+$pane.height-20;$y+=11){$null=$colors.Add($image.GetPixel($x,$y).ToArgb())}};$center=$image.GetPixel([int]($pane.x+$pane.width/2),[int]($pane.y+$pane.height/2));Check ($shell.G-gt100-and$colors.Count-ge2-and$center.R-gt60) 'offscreen capture contains the real frame and decoded video rather than a blank bitmap';$image.Save("$root/television-sage.png")}finally{$image.Dispose()};$stable=FrameHash;$same=$true;for($i=0;$i-lt12;$i++){if((FrameHash)-ne$stable){$same=$false}};Check $same 'repeated native paints retain the same paused video pixels'
 foreach($palette in @('sage','walnut','ivory')){Appearance 'television' $palette;Check ((Tv).frame_palette-eq$palette-and[math]::Abs((Tv).position_seconds-$position)-lt.03) "palette changes preserve playback $palette";$image=Bitmap;try{$image.Save("$root/television-$palette.png")}finally{$image.Dispose()}}
 Appearance 'window' 'sage';Check (([ChatWindowTest]::GetWindowLongPtrW($window,-16).ToInt64()-band0xC00000)-ne0-and![ChatWindowTest]::IsWindowVisible($play)) 'classic window remains available';Appearance 'television' 'sage';Check ([TvWindow]::Rounded($window)-and[math]::Abs((Tv).position_seconds-$position)-lt.03) 'switching frame styles preserves the decoded frame and clock'
 $gdi=[PrivateDesktop]::GetGuiResources($service.Handle,0);for($i=0;$i-lt24;$i++){$width=if($i%2){320}else{760};$height=if($i%2){220}else{460};$null=[TvWindow]::SetWindowPos($window,[IntPtr]::Zero,0,0,$width,$height,0x16)};$null=[TvWindow]::SetWindowPos($window,[IntPtr]::Zero,0,0,480,320,0x16);Start-Sleep -Milliseconds 150;Check ([PrivateDesktop]::GetGuiResources($service.Handle,0)-le$gdi+6) 'resizing releases old buffers and window regions'
 $null=Api '/api/control' @{paused=$true};$null=[ChatWindowTest]::Send($window,0x111,3502);Start-Sleep -Milliseconds 200;Check ((Tv).state-eq'paused'-and![ChatWindowTest]::IsWindowEnabled($play)) 'background pause prevents a native control from restarting playback';$null=Api '/api/control' @{paused=$false};Check ((Tv).state-eq'paused') 'resume does not automatically replay video';$null=[ChatWindowTest]::Send($window,0x100,32);Wait-For {(Tv).state-eq'playing'} 'space resumes video';$null=[ChatWindowTest]::Send($window,0x111,3501);Wait-For {![ChatWindowTest]::IsWindowVisible($window)-and(Tv).state-eq'paused'} 'power control hides and pauses';$null=Api '/api/surfaces/show' @{id='television'};Wait-For {[ChatWindowTest]::IsWindowVisible($window)} 'reopened';Check ((Tv).visible-and(Tv).state-eq'paused') 'hidden television can reopen without replaying the film'
 $web=Plugin 'television.open_page' @{url=$fixture+'/fixture/tv-chrome';platform='fixture'};Check $web.ok 'web video opens in the inner owned surface';$observed=Plugin 'television.observe' @{include_frame=$false};Check ($observed.ok-and$observed.result.title-eq'电视边框验证') 'embedded webpage remains observable';$surface=[ChatWindowTest]::GetDlgItem($window,3500);Wait-For {[ChatWindowTest]::IsWindowVisible($surface)} 'web surface';$bounds=[TvWindow]::ChildBounds($window,$surface);$pane=(Tv).screen_rect;Check ($bounds[0]-eq$pane.x-and$bounds[1]-eq$pane.y-and$bounds[2]-eq$pane.width-and$bounds[3]-eq$pane.height) 'website bounds stay inside the same television screen';$null=[ChatWindowTest]::Send($window,0x111,3502);Wait-For {$script:webState=Plugin 'television.observe' @{include_frame=$false};$webState.ok-and!$webState.result.video.paused} 'web native play toggle';$null=[ChatWindowTest]::Send($window,0x100,32);Wait-For {$script:webState=Plugin 'television.observe' @{include_frame=$false};$webState.ok-and$webState.result.video.paused} 'web space pause';Check $true 'native controls operate the actual website player too'
 $null=[TvWindow]::SetWindowPos($window,[IntPtr]::Zero,0,0,640,400,0x16);$bounds=[TvWindow]::ChildBounds($window,$surface);$pane=(Tv).screen_rect;Check ($bounds[2]-eq$pane.width-and$bounds[3]-eq$pane.height) 'website resizing follows the inner screen';$settings=(Api '/api/dashboard').settings;$settings.plugins.television.enabled=$false;$null=Api '/api/settings' @{settings=$settings};Check ($desktop.Find('HibernationFloatingTelevision')-eq[IntPtr]::Zero) 'unloading releases the frame and browser parent'
 $null=Api '/api/shutdown' @{};Check ($service.WaitForExit(10000)-and$service.ExitCode-eq0) 'television chrome process exits cleanly';@{completed=$true;checks=$checks;root=$root;timestamp=[DateTime]::UtcNow.ToString('O')}|ConvertTo-Json|Set-Content "$root/acceptance.json";Write-Output "Television desktop passed: $checks checks. Evidence: $root"
}finally{if($service){$service.Refresh();if(!$service.HasExited){try{$null=Api '/api/shutdown' @{};$service.WaitForExit(5000)|Out-Null}catch{};$service.Refresh();if(!$service.HasExited){Stop-Process -Id $service.Id}}};if($desktop){$desktop.Dispose()};if($provider){$provider.Refresh();if(!$provider.HasExited){Stop-Process -Id $provider.Id}}}
